64→            fontSize: 'clamp(1.5rem, 3vw, 2.5rem)',
65→            lineHeight: 1.25,
66→            marginBottom: project.client ? 'var(--space-tiny)' : 0
67→          }}
68→        >
69→          {project.title}
70→        </h3>
71→
72→        {/* Client as footnote - dimmest, true metadata */}
73→        {project.client ? (
74→          <p
75→            style={{
76→              color: 'var(--text-dim)',
77→              fontFamily: 'var(--font-display)',
78→              fontWeight: 500,
79→              fontSize: '11px',
80→              letterSpacing: '0.12em',
81→              textTransform: 'uppercase'
82→            }}
83→          >
84→            {project.client}
85→          </p>
86→        ) : null}
87→      </Link>
88→    </article>
89→  );
90→}
