227→/* ===========================================
228→   ENTRANCE ANIMATIONS
229→   =========================================== */
230→
231→@keyframes fadeUp {
232→  from {
233→    opacity: 0;
234→    transform: translateY(21px);  /* Fibonacci */
235→  }
236→  to {
237→    opacity: 1;
238→    transform: translateY(0);
239→  }
240→}
241→
242→.project-card {
243→  opacity: 0;
244→  animation: fadeUp 0.7s ease-out forwards;
245→}
246→
247→.project-card:nth-child(1) { animation-delay: 0ms; }
248→.project-card:nth-child(2) { animation-delay: 80ms; }
249→.project-card:nth-child(3) { animation-delay: 160ms; }
250→.project-card:nth-child(4) { animation-delay: 240ms; }
251→.project-card:nth-child(5) { animation-delay: 320ms; }
252→.project-card:nth-child(6) { animation-delay: 400ms; }
253→
254→@keyframes fadeIn {
255→  from { opacity: 0; }
256→  to { opacity: 1; }
257→}
258→
259→.client-strip {
260→  animation: fadeIn 0.8s ease-out forwards;
261→  animation-delay: 200ms;
262→  opacity: 0;
263→}
264→
265→/* Scroll indicator */
266→@keyframes scrollFloat {
267→  0%, 100% {
268→    transform: translateY(0);
269→    opacity: 0.5;
270→  }
271→  50% {
272→    transform: translateY(6px);
273→    opacity: 0.8;
274→  }
275→}
276→
277→.scroll-chevron {
278→  animation: scrollFloat 2.8s ease-in-out infinite;
279→  will-change: transform, opacity;
280→}
281→
282→/* Availability indicator */
283→@keyframes availabilityPulse {
284→  0%, 100% { opacity: 0.6; }
285→  50% { opacity: 1; }
286→}
287→
288→.availability-dot {
289→  animation: availabilityPulse 2.5s ease-in-out infinite;
290→}
291→
292→/* Chat typing indicator */
293→@keyframes typingPulse {
294→  0%, 100% {
295→    opacity: 0.3;
296→    transform: scale(1);
297→  }
298→  50% {
299→    opacity: 1;
300→    transform: scale(1.15);
301→  }
302→}
303→
304→.typing-dot {
305→  will-change: transform, opacity;
306→}
307→
308→/* Chat message entrance */
309→@keyframes chatMessageIn {
310→  from {
311→    opacity: 0;
312→    transform: translateY(13px);  /* --space-small: 21 / phi */
313→  }
314→  to {
315→    opacity: 1;
316→    transform: translateY(0);
317→  }
318→}
319→
320→.chat-message-enter {
321→  animation: chatMessageIn 0.3s ease-out forwards;
322→}
323→
324→/* Reduced motion */
325→@media (prefers-reduced-motion: reduce) {
326→  html {
327→    scroll-behavior: auto;
328→  }
329→
330→  *,
331→  *::before,
332→  *::after {
333→    animation-duration: 0.01ms !important;
334→    animation-iteration-count: 1 !important;
335→    transition-duration: 0.01ms !important;
336→  }
337→
338→  [aria-live="polite"] {
339→    transition: none !important;
340→  }
341→
342→  .nav-link,
343→  .project-title h3,
344→  .section-header-highlight,
345→  .project-card,
346→  .nav-item-shift,
347→  .button-arrow,
348→  .scroll-chevron,
349→  .typing-dot,
350→  .chat-message-enter {
351→    transition: none !important;
352→    transform: none !important;
353→    animation: none !important;
354→  }
355→}
356→
357→/* ===========================================
358→   FOCUS INDICATORS FOR ACCESSIBILITY
359→   =========================================== */
360→
361→/* Focus-visible indicators for keyboard navigation */
362→:focus-visible {
363→  outline: 2px solid rgba(255, 255, 255, 0.5);
364→  outline-offset: 2px;
365→}
366→
367→/* Remove focus ring on mouse click, keep for keyboard */
368→:focus:not(:focus-visible) {
369→  outline: none;
370→}
371→
372→/* ===========================================
373→   VIEW TRANSITIONS - Cinematic Page Crossfades
374→   =========================================== */
375→
376→/*
377→ * Design philosophy:
378→ * - Film dissolve feel, not flashy web animation
379→ * - Content: subtle crossfade with micro-scale for depth
380→ * - Navigation: fade only (no scale/position change - stays anchored)
381→ * - Duration: 500ms content, 400ms nav (slow enough to feel intentional)
382→ * - Easing: ease-in-out for cinematic linear-ish blend
383→ */
384→
385→/* Dark canvas behind all transition layers — prevents white bleed-through */
386→::view-transition {
387→  background-color: #141414;
388→}
389→
390→::view-transition-group(root),
391→::view-transition-group(navigation),
392→::view-transition-group(footer) {
393→  background-color: #141414;
394→}
395→
396→/* Root (main content) transition */
397→::view-transition-old(root),
398→::view-transition-new(root) {
399→  animation-duration: 500ms;
400→  animation-timing-function: ease-in-out;
401→}
402→
403→/* Old page: fade out with slight scale down */
404→::view-transition-old(root) {
405→  animation-name: fade-and-scale-out;
406→}
407→
408→/* New page: fade in with slight scale up */
409→::view-transition-new(root) {
410→  animation-name: fade-and-scale-in;
411→}
412→
413→@keyframes fade-and-scale-out {
414→  from {
415→    opacity: 1;
416→    transform: scale(1);
417→  }
418→  to {
419→    opacity: 0;
420→    transform: scale(0.98);
421→  }
422→}
423→
424→@keyframes fade-and-scale-in {
425→  from {
426→    opacity: 0;
427→    transform: scale(1.02);
428→  }
429→  to {
430→    opacity: 1;
431→    transform: scale(1);
432→  }
433→}
434→
435→/* Navigation: fade only, no scale (stays anchored) */
436→::view-transition-old(navigation),
437→::view-transition-new(navigation) {
438→  animation-duration: 400ms;
439→  animation-timing-function: ease-in-out;
440→}
441→
442→::view-transition-old(navigation) {
443→  animation-name: fade-out-only;
444→}
445→
446→::view-transition-new(navigation) {
447→  animation-name: fade-in-only;
448→}
449→
450→/* Hero reel: fade only, no scale (prevents white flash from iframe reinit) */
451→/* Dark background on the transition group prevents white bleed-through during crossfade */
452→::view-transition-group(hero-reel) {
453→  background-color: #141414;
454→}
455→
456→::view-transition-old(hero-reel),
457→::view-transition-new(hero-reel) {
458→  animation-duration: 400ms;
459→  animation-timing-function: ease-in-out;
460→}
461→
462→::view-transition-old(hero-reel) {
463→  animation-name: fade-out-only;
464→}
465→
466→::view-transition-new(hero-reel) {
467→  animation-name: fade-in-only;
468→}
469→
470→/* Footer: fade only, no scale (stays anchored) */
471→::view-transition-old(footer),
472→::view-transition-new(footer) {
473→  animation-duration: 400ms;
474→  animation-timing-function: ease-in-out;
475→}
476→
477→::view-transition-old(footer) {
478→  animation-name: fade-out-only;
479→}
480→
481→::view-transition-new(footer) {
482→  animation-name: fade-in-only;
483→}
484→
485→@keyframes fade-out-only {
486→  from { opacity: 1; }
487→  to { opacity: 0; }
488→}
489→
490→@keyframes fade-in-only {
491→  from { opacity: 0; }
492→  to { opacity: 1; }
493→}
494→
495→/* Respect reduced motion */
496→@media (prefers-reduced-motion: reduce) {
497→  ::view-transition-old(root),
498→  ::view-transition-new(root),
499→  ::view-transition-old(navigation),
500→  ::view-transition-new(navigation),
501→  ::view-transition-old(hero-reel),
502→  ::view-transition-new(hero-reel),
503→  ::view-transition-old(footer),
504→  ::view-transition-new(footer) {
505→    animation: none !important;
506→  }
507→}
